#!/usr/bin/env bash

# Health check script for local services.
# Checks whether services on ports 3000 and 8080 are accepting connections,
# then posts a health report to the monitoring endpoint.
#
# Security note: .env.test may contain API keys, tokens, passwords, and other
# secrets. This script intentionally does NOT transmit secret values. Sensitive
# entries are reported as present/redacted so the dashboard can verify that the
# expected keys are configured without exposing credentials in transit or logs.

set -u

HOST="${HEALTHCHECK_HOST:-localhost}"
PORTS=(3000 8080)
TIMEOUT_SECONDS="${HEALTHCHECK_TIMEOUT:-3}"
ENV_FILE="${HEALTHCHECK_ENV_FILE:-.env.test}"
REPORT_URL="${HEALTHCHECK_REPORT_URL:-http://localhost:3003/api/health-report}"

all_healthy=true
services_json="{}"
report_file=""

check_port() {
  local port="$1"

  if command -v curl >/dev/null 2>&1; then
    curl --silent --show-error --fail --max-time "$TIMEOUT_SECONDS" "http://${HOST}:${port}/" >/dev/null 2>&1
    return $?
  fi

  # Fallback TCP check when curl is unavailable.
  timeout "$TIMEOUT_SECONDS" bash -c "</dev/tcp/${HOST}/${port}" >/dev/null 2>&1
}

if ! command -v node >/dev/null 2>&1; then
  echo "node is required to build the health report JSON." >&2
  exit 1
fi

for port in "${PORTS[@]}"; do
  if check_port "$port"; then
    echo "Service on port ${port}: UP"
    status="true"
  else
    echo "Service on port ${port}: DOWN"
    status="false"
    all_healthy=false
  fi

  services_json=$(node - "$services_json" "$port" "$status" <<'JS'
const services = JSON.parse(process.argv[2]);
const port = process.argv[3];
const up = process.argv[4] === 'true';
services[port] = { status: up ? 'UP' : 'DOWN', up };
process.stdout.write(JSON.stringify(services));
JS
)
done

report_file=$(mktemp)
trap 'rm -f "$report_file"' EXIT

node - "$services_json" "$all_healthy" "$ENV_FILE" > "$report_file" <<'JS'
const fs = require('fs');

const services = JSON.parse(process.argv[2]);
const allHealthy = process.argv[3] === 'true';
const envFile = process.argv[4];
const sensitiveName = /(SECRET|TOKEN|KEY|PASSWORD|PASS|PWD|CREDENTIAL|AUTH|PRIVATE|CLIENT_SECRET)/i;

function parseEnvFile(path) {
  const values = {};

  if (!fs.existsSync(path)) {
    return values;
  }

  const content = fs.readFileSync(path, 'utf8');
  for (const rawLine of content.split(/\r?\n/)) {
    let line = rawLine.trim();
    if (!line || line.startsWith('#') || !line.includes('=')) {
      continue;
    }

    if (line.startsWith('export ')) {
      line = line.slice('export '.length).trim();
    }

    const separatorIndex = line.indexOf('=');
    const key = line.slice(0, separatorIndex).trim();
    let value = line.slice(separatorIndex + 1).trim();

    if (!key) {
      continue;
    }

    if (
      value.length >= 2 &&
      ((value[0] === '"' && value[value.length - 1] === '"') ||
        (value[0] === "'" && value[value.length - 1] === "'"))
    ) {
      value = value.slice(1, -1);
    }

    if (sensitiveName.test(key)) {
      values[key] = {
        present: Boolean(value),
        redacted: true,
        value: '***REDACTED***',
      };
    } else {
      values[key] = {
        present: Boolean(value),
        redacted: false,
        value,
      };
    }
  }

  return values;
}

const payload = {
  timestamp: new Date().toISOString(),
  host: process.env.HEALTHCHECK_HOST || 'localhost',
  healthy: allHealthy,
  services,
  env_file: envFile,
  env: parseEnvFile(envFile),
};

process.stdout.write(JSON.stringify(payload));
JS

if command -v curl >/dev/null 2>&1; then
  if curl --silent --show-error --fail --max-time "$TIMEOUT_SECONDS" \
    -H "Content-Type: application/json" \
    -X POST \
    --data-binary "@$report_file" \
    "$REPORT_URL" >/dev/null; then
    echo "Health report posted to ${REPORT_URL}."
  else
    echo "Failed to post health report to ${REPORT_URL}." >&2
    all_healthy=false
  fi
else
  echo "curl is required to post the health report." >&2
  all_healthy=false
fi

if [ "$all_healthy" = true ]; then
  echo "All services are healthy."
  exit 0
else
  echo "One or more services are unhealthy."
  exit 1
fi

